    const spr = (s, t, k, d, dt) => { s.v += (t - s.x) * k * dt; s.v *= Math.exp(-d * dt); s.x += s.v * dt; };
    let walkPhase = 0, walkT = 0, actionT = 0, jumpT = 0, turn = 0, time = 0, pose = null, forcedMove = null;
